import subprocess
def run(args):
    p=subprocess.run(["./executable"]+args, capture_output=True, text=True)
    return p
def single_n(n, pattern):
    # pattern: "inc", "dec", "stable", "spike_end"
    with open(f"/tmp/rhit_test/trend_{n}_{pattern}.log","w") as f:
        for d in range(1,n+1):
            if pattern=="inc":
                c=d
            elif pattern=="dec":
                c=n-d+1
            elif pattern=="stable":
                c=5
            elif pattern=="spike_end":
                c=20 if d==n else 5
            elif pattern=="spike_start":
                c=20 if d==1 else 5
            for i in range(c):
                f.write(f'1.1.1.1 - - [{d:02d}/Oct/2023:12:00:00 +0000] "GET /a HTTP/1.1" 200 100 "-" "M"\n' if n<=31 else f'1.1.1.1 - - [{d:02d}/Oct/2023:12:00:00 +0000] "GET /a HTTP/1.1" 200 100 "-" "M"\n')
    # For n>31, need Nov dates? Simplify: use Oct for 1..31, Nov for 32.. etc. But our loop uses Oct with d>31 invalid. Let's handle.
    p=run(["--color","no","--silent-load","-f","p",f"/tmp/rhit_test/trend_{n}_{pattern}.log"])
    for L in p.stdout.splitlines():
        if "/a" in L:
            print(f"n={n} {pattern} => {repr(L)}")
            break
    else:
        print(f"n={n} {pattern} => NO /a line, stdout={repr(p.stdout[:500])}")

for n in [4,5,6,10,11,15,20,21,25,31]:
    for pat in ["inc","dec","stable","spike_end"]:
        # need to handle date generation for n up to 31, Oct has 31 days, ok
        single_n(n, pat)
